//! A model earns the default only on measured error, per check type: the false-accept
//! rate (an unsupported claim judged supported) with a Wilson 95% interval (Wilson
//! 1927), the abstain rate, and balanced accuracy on the claims it decided. The
//! coverage floor and the abstain cap stop a model that always says `cannot_tell`
//! from winning on a clean false-accept rate.

/// First lane port. The range sits well above the local Ollama (11434) and the plain
/// lane (11435, runner 11436), so no lane can ever be either.
pub const LANE_PORT_BASE: u16 = 11500;
/// Lane ports are two apart: the lane's own port, and the one above it for the
/// handoff runner's second tunnel.
pub const LANE_PORT_STEP: u16 = 2;
/// How many lanes the range holds.
pub const LANE_COUNT: u16 = 64;

/// Delay-seconds from `Retry-After`. An HTTP-date or a missing header waits one second.
fn retry_after(headers: &ureq::http::HeaderMap) -> Duration {
    let Some(raw) = headers.get("retry-after").and_then(|v| v.to_str().ok()) else {
        return Duration::from_secs(1);
    };
    let raw = raw.trim();
    if let Ok(secs) = raw.parse::<u64>() {
        return Duration::from_secs(secs);
    }
    if let Ok(secs) = raw.parse::<f64>()
        && secs.is_finite()
        && secs >= 0.0
    {
        return Duration::from_secs_f64(secs);
    }
    Duration::from_secs(1)

