pub const MAX_ABSTAIN: f64 = 0.20;
pub const MIN_BALANCED_ACCURACY: f64 = 0.80;
pub const MIN_UNSUPPORTED: usize = 100;

pub const LANE_COUNT: u16 = 64;
/// First default side-car port: the port a project's shell-driven side-car listens on
/// (loopback HTTP, in front of `offrig-mcp`). Lane `i` gets `SIDECAR_PORT_BASE + i`.
/// The range 11700..=11763 sits above every tunnel and runner port a lane can have
/// (11500..=11627), the plain lane (11435, 11436) and the local Ollama (11434), so a
/// side-car port can never be a tunnel port. It replaces the one machine-wide default
/// (11439) that two projects shared (issue #11).
pub const SIDECAR_PORT_BASE: u16 = 11700;

/// How many times a 429 on `POST /pods` is retried on the same GPU type.
/// The first request is not counted. A retry waits for `Retry-After` and does
/// not run past the plan deadline. A missing or unreadable `Retry-After` waits
/// one second. The next GPU type is not tried.
pub const CREATE_429_RETRIES: u32 = 3;

/// The default rule's thresholds.
pub const MAX_FALSE_ACCEPT_UPPER: f64 = 0.10;
pub const MAX_ABSTAIN: f64 = 0.20;
pub const MIN_BALANCED_ACCURACY: f64 = 0.80;
pub const MIN_UNSUPPORTED: usize = 100;

/// `None` has no plan clock, so the attempt cap is the only bound. A set deadline
/// refuses a sleep that would end after it.
fn retry_fits(deadline: Option<Instant>, delay: Duration) -> bool {
    let Some(end) = deadline else {
        return true;
    };
    Instant::now()
        .checked_add(delay)
        .is_some_and(|wake| wake <= end)
}

